# -*- coding: utf-8 -*-
"""Круг 48: правила 15zm. в 17_ и пересъём чисел README лана."""
import pathlib, re

R = pathlib.Path("/home/user/Research/ИСКУПЛЕНИЕ/17_RECONCILIATION_WITH_CANONICAL_SPINE_2026-10-15.md")
TXT = """
### 15zm. Круг 48 (25.10.2026, вечер после круга 47): четыре правила о том, как опознавать труд — и как опознать его зря

1. **Труд опознаётся по автору; фрагмент заглавия — улика, а не идентификация.** Из десяти адресов, которые круг 47 пометил как «цитируемые» (у строки есть латинская или английская формула, ищущаяся в тексте), девять привели к чужим печатным книгам, и у каждой подмены есть механизм, который стоит назвать по имени: Q-02 вёл в *Capitula siue constitutiones ecclesiasticæ* кентерберийского синода 1597 г. — зацепилось слово «Capitula» из строки о *Capitula* Проспера; Q-81 — в *Blessedness, or, God and the world weighted in the balances of the sanctuary* Фрэнсиса Роуорта (1656) за слово «Balances» из «*Balances?*» Уордлоу; Q-64 — в роялистский ответ «G. G.» о речи Чэлонера (1642) за фразу «interest of the kingdome», **которую круг 46 сам вписал в адрес очереди**; Q-74 — в *The Rambler* Сэмюэла Джонсона за год 1752. Отсюда порядок сверки: сначала `Author` в каталоге, потом `titleStmt` самой TEI-записи, и только потом слова строки. Тот же порядок требует осторожности и со счётом: подстрочник «prosper» даёт 12 записей, и все ложны («vnhappy prosperitie», «a prosper fall»).

2. **Попадание на титульной странице — не попадание.** Гибкий поиск по десяти файлам вернул два попадания, и оба сидели на странице `pre`, то есть на титуле: «nunc primum editi» и «interest of the kingdome» — эхо каталожного заглавия и слов самой строки, а не тело книги. Поиск обязан исключать фронтматтер и называть страницу попадания: «hit» без страницы измеряет совпадение строк, а не наличие цитаты. Реальное покрытие цитатами после такой поправки — 0 из 10, а не 2 из 10.

3. **Прочитанная страница важнее формулы, с которой в неё пришли.** Если чтение противоречит wording строки, wording и умирает: у `FP-74` оставалось требование *Works* 1752 г. и поиск фразы «universal redemption»; фразы нет ни в одном доступном томе проповедей (0 вхождений), требование снято, потому что страницы 1695 и 1700 гг. держат ровно то, что строка хотела сказать. Обратная половина правила обязана работать так же жёстко: если страница даёт различение, но не даёт формулу строки, класс не повышается — A15859 Занки держит «the free love of God, eternall and vnchangeable towards his Elect», но не держит «equal love», и адрес остался `C`. Поднятие класса — это цитата на напечатанной странице, а не скачанный файл рядом с темой.

4. **Наследовать номер книги или номер проповеди — то же, что наследовать цитату.** «Кн. III» у Брэдвардина жила в строке со времён индекса и оказалась неподтверждаемой: единственный явный заголовок книги в томе 1618 г. («liber primus») стоит на с. 441, а нужные страницы — 242 и 250. Следствие общее и для английских томов: слой пагинации сверяется на каждом тексте, а не переносится с прошлого. Круг 48 проверил его явно: у N03743 `<pb n=>` совпадает с напечатанной нумерацией 9–160, у A62570 и A62579 — с непрерывной нумерацией проповедей внутри тома, у A16626 — с напечатанной пагинацией 1–876; там, где совпадение не установлено, локатор даётся «по напечатанной пагинации тома», а не по книге или главе.

Правила записаны после похода, а не до него: каждый из четырёх пунктов стоил бы кругу трёх ложных повышений, стой они в начале, и ровно поэтому стоят в конце — как то, что следующая проверка обязана ловить сама, а не то, что автор обещает помнить.
"""
s = R.read_text(encoding="utf-8")
assert "### 15zm." not in s, "правила уже внесены"
CJK = re.compile(r"[\u3040-\u30ff\u4e00-\u9fff]")
assert not CJK.search(TXT), "CJK в новых правилах"
s = s.rstrip("\n") + "\n" + TXT.strip("\n") + "\n"
R.write_text(s, encoding="utf-8")
t = R.read_text(encoding="utf-8")
lines = len(t.rstrip("\n").split("\n"))
h2 = len(re.findall(r"^## ", t, re.M))
h3 = len(re.findall(r"^### ", t, re.M))
print("17_: байт", len(t.encode()), "| строк", lines, "| H2", h2, "| H3", h3)

D = pathlib.Path("/home/user/Research/docs/research/atonement/README.md")
r = D.read_text(encoding="utf-8")
reps = [
    ("`A1` прочитано по изданию (34)", "`A1` прочитано по изданию (37)"),
    ("`C` требуется добыча (100)", "`C` требуется добыча (97)"),
    ("(адресатов — 100; сняты Q-65 и Q-67 — первое сокращение очереди с круга 21)",
     "(адресатов — 97; сняты Q-65 и Q-67 кругом 47, Q-22, Q-74 и Q-78 кругом 48 — крупнейшее сокращение очереди "
     "с круга 21)"),
    ("Круг 47 поднял две строки (FP-65 и FP-67) до `A1`, снял два адреса очереди и вернул в открытое состояние "
     "адрес Q-164, который круг 46 считал подтверждённым;",
     "Круг 47 поднял две строки (FP-65 и FP-67) до `A1`, снял два адреса очереди и вернул в открытое состояние "
     "адрес Q-164, который круг 46 считал подтверждённым; круг 48 поднял три строки (FP-22, FP-74, FP-78) до `A1` "
     "по прочитанным напечатанным страницам (A16626, с. 250; A62570, с. 366 и A62579, с. 44; N03743, с. 64), снял "
     "три адреса и отозвал девять из десяти опознаний труда, которые круг 47 сделал по фрагментам заглавий;"),
    ("**доля прочитанного по первичному — 16 %**, с круга 42 оба определения совпали и с круга 47 совпадают "
     "(34·100/209 = 16.27: округление правила 23 и целочисленное деление дают одно число), а с круга 24 по круг 41 "
     "они расходились на пункт и это было записано как расхождение определений, а не как ошибка",
     "**доля прочитанного по первичному — 17 %**, и с круга 48 оба определения снова расходятся: 37·100/209 = 17.70, "
     "целочисленное деление даёт 17, округление правила 23 — 18; расхождение названо здесь, а не сглажено (с круга "
     "42 по круг 47 определения совпадали: 32·100/209 = 15.31 и 34·100/209 = 16.27 давали одно число, а с круга 24 "
     "по круг 41 они расходились на пункт, и это было записано как расхождение определений, а не как ошибка)"),
]
for a, b in reps:
    if r.count(a) != 1:
        raise SystemExit("README: якорь встретился %d раз: %s" % (r.count(a), a[:70]))
    r = r.replace(a, b, 1)
assert not CJK.search(r), "CJK в README"
D.write_text(r, encoding="utf-8")
print("README: байт", len(r.encode()))
